#!/usr/bin/env python3
"""
Genera src/VedettaVip.Web.Client/Services/MapIcons.g.cs dalle icone Tabler (MIT) in icons/.

Aggiungere un'icona:
  1. scaricare il pacchetto:  curl -sL https://registry.npmjs.org/@tabler/icons/-/icons-<versione>.tgz | tar -xz
  2. copiare package/icons/outline/<nome>.svg in icons/ e aggiungere <nome> con l'etichetta a ICONS qui sotto
  3. python3 third-party/tabler-icons/generate.py   (dalla radice del repository)
"""
import pathlib, re

# Ordine = ordine nel selettore. Chiave = nome Tabler (salvato in Device.Icon / MapNode.Icon).
ICONS = [
    ("router", "Router"), ("topology-bus", "Switch"), ("switch-3", "Switch (frecce)"), ("access-point", "Access point"),
    ("wifi", "Wi-Fi"), ("antenna", "Antenna"), ("antenna-bars-5", "Segnale"), ("broadcast", "Radio"),
    ("building-broadcast-tower", "Ponte radio"), ("satellite", "Satellite"), ("server", "Server"), ("server-2", "Rack"),
    ("server-cog", "Server applicativo"), ("database", "Storage / NAS"), ("cpu", "Appliance"),
    ("firewall-flame", "Firewall"), ("firewall-check", "Firewall (ok)"), ("shield-lock", "Sicurezza / VPN"),
    ("load-balancer", "Load balancer"), ("network", "Rete"), ("topology-star-3", "Topologia"), ("sitemap", "Sottomappa"),
    ("cloud", "Cloud"), ("world", "Internet"), ("building", "Sede"), ("home", "Casa / filiale"),
    ("device-desktop", "PC"), ("device-laptop", "Portatile"), ("device-mobile", "Smartphone"), ("device-tv", "Display"),
    ("printer", "Stampante"), ("device-cctv", "Telecamera"), ("camera", "Fotocamera"), ("device-landline-phone", "Telefono VoIP"),
    ("phone", "Telefono"), ("battery-charging", "UPS"), ("plug-connected", "Alimentazione"), ("bolt", "Energia"),
    ("box", "Altro"),
]

root = pathlib.Path(__file__).resolve().parent
out = root.parent.parent / "src/VedettaVip.Web.Client/Services/MapIcons.g.cs"
version = (root / "VERSION").read_text().strip()

entries = []
for key, label in ICONS:
    svg = (root / "icons" / f"{key}.svg").read_text()
    body = re.search(r"<svg[^>]*>(.*)</svg>", svg, re.S).group(1)
    body = re.sub(r'<path stroke="none" d="M0 0h24v24H0z" fill="none"\s*/>', "", body)  # riquadro trasparente
    body = re.sub(r"\s+", " ", body).strip().replace('"', '""')
    entries.append(f'        new("{key}", "{label}", @"{body}"),')

out.write_text(f"""// <auto-generated>
// Generato da third-party/tabler-icons/generate.py da Tabler Icons {version} (MIT, https://tabler.io/icons):
// non modificare a mano.
// </auto-generated>

namespace VedettaVip.Web.Client.Services;

public static partial class MapIcons
{{
    /// <summary>Icone disponibili: chiave Tabler, etichetta, contenuto SVG (viewBox 0 0 24 24, tratto currentColor).</summary>
    public static readonly IReadOnlyList<MapIcon> All =
    [
{chr(10).join(entries)}
    ];
}}
""")
print(f"{len(entries)} icone → {out}")
